import { Component, Input, OnChanges } from '@angular/core';
import { IsActiveMatchOptions } from '@angular/router';
import { MessageConfig, MessageModule } from 'espd-common/i18n';

@Component({
	selector: 'espd-sidenav',
	templateUrl: './sidenav.component.html',
	styleUrls: ['./sidenav.component.scss'],
	imports: [MessageModule]
})
export class SidenavComponent implements OnChanges {

	public static defaultActiveMatchOptions: IsActiveMatchOptions = {
		fragment: 'ignored',
		matrixParams: 'ignored',
		paths: 'exact',
		queryParams: 'ignored'
	}

	private static nextId = 0;

	@Input()
	public label?: string | MessageConfig;

	@Input()
	public linkActiveOptions: Partial<IsActiveMatchOptions> = SidenavComponent.defaultActiveMatchOptions;

	private matchOptions = SidenavComponent.defaultActiveMatchOptions

	public id: number;

	constructor() {
		this.id = SidenavComponent.nextId++;
	}

	public ngOnChanges(): void {
		// This is a bit odd, but if the value is computed directly in the getter for isActiveMatchOptions, an infinite loop occurs
		this.matchOptions = { ...SidenavComponent.defaultActiveMatchOptions, ...this.linkActiveOptions };
	}

	public get isActiveMatchOptions(): IsActiveMatchOptions {
		return this.matchOptions;
	}
}
