import { CommonModule } from '@angular/common';
import { Component, HostBinding, Input, OnChanges, ViewChild, inject } from '@angular/core';
import { IsActiveMatchOptions, Params, RouterLinkActive, RouterModule } from '@angular/router';
import { SidenavComponent } from '../sidenav.component';

@Component({
	selector: 'espd-sidenav-item',
	templateUrl: './sidenav-item.component.html',
	styleUrls: ['./sidenav-item.component.scss', '../sidenav-item.scss'],
	imports: [CommonModule, RouterModule]
})
export class SidenavItemComponent implements OnChanges {

	@Input() public route?: string;
	@Input() public queryParams: Params | null = null;
	@Input() public href?: string;
	@Input() public target?: 'blank' | 'self';
	@Input() public linkActiveOptions: Partial<IsActiveMatchOptions> = {};

	// internal use only
	@Input() public clickable = true;

	@HostBinding('class.nested')
	public nested = false;

	@HostBinding('attr.role')
	public get role(): string | null {
		return this.clickable ? 'listitem' : null;
	}

	@ViewChild('rla')
	private routerLinkActive?: RouterLinkActive;

	private parentSidenav: SidenavComponent = inject(SidenavComponent);

	public isActiveMatchOptions: IsActiveMatchOptions = SidenavComponent.defaultActiveMatchOptions;

	public ngOnChanges(): void {
		// This is a bit odd, but if the value is computed directly in the getter for isActiveMatchOptions, an infinite loop occurs
		this.isActiveMatchOptions = { ...this.parentSidenav.isActiveMatchOptions, ...this.linkActiveOptions };
	}

	public get isActive(): boolean {
		return this.routerLinkActive?.isActive ?? false;
	}
}
