import { AfterContentInit, AfterViewInit, Component, ContentChildren, inject, Input, QueryList, ViewChild } from '@angular/core';
import { RouterModule } from '@angular/router';
import { MessageConfig, MessageModule, MessageService } from 'espd-common/i18n';
import { CollapseModule } from 'ngx-bootstrap/collapse';
import { SidenavItemComponent } from '../sidenav-item/sidenav-item.component';

@Component({
	selector: 'espd-sidenav-list',
	templateUrl: './sidenav-list.component.html',
	styleUrls: ['./sidenav-list.component.scss', '../sidenav-item.scss', '../sidenav-list.scss'],
	providers: [{ provide: SidenavItemComponent, useExisting: SidenavListComponent }],
	imports: [CollapseModule, MessageModule, RouterModule, SidenavItemComponent]
})
export class SidenavListComponent extends SidenavItemComponent implements AfterContentInit, AfterViewInit {

	private static nextId = 0;
	private messageService = inject(MessageService);

	@Input() public label?: string | MessageConfig;
	@Input() public srLabel?: string | MessageConfig;
	@Input() public isCollapsed = true;

	@ContentChildren(SidenavItemComponent)
	public children!: QueryList<SidenavItemComponent>;

	@ViewChild('navItem')
	private navItem!: SidenavItemComponent;

	readonly id = SidenavListComponent.nextId++;

	public get isActive(): boolean {
		return this.navItem.isActive || this.hasActiveChild();
	}

	public get resolvedSrLabel(): string | undefined {
		return this.messageService.evaluate(this.srLabel ?? this.label ?? '');
	}

	public ngAfterContentInit(): void {
		this.updateChildren();
		this.children.changes.subscribe(() => this.updateChildren());
	}

	public ngAfterViewInit(): void {
		setTimeout(() => {
			this.navItem.nested = this.nested;

			// If a child is active, open the list
			if (this.hasActiveChild()) {
				this.isCollapsed = false;
			}
		});
	}

	public isClickable(): boolean {
		return !(!!this.href || !!this.route);
	}

	private updateChildren(): void {
		setTimeout(() => {
			this.children.forEach(c => {
				c.nested = true;
			});
		});
	}

	private hasActiveChild(): boolean {
		return this.children.reduce((prev, c) => prev || c.isActive, false);
	}
}